WITH enriched AS (SELECT *, FIRST_VALUE(balance) IGNORE NULLS OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_balance, NTILE(4) OVER (PARTITION BY status ORDER BY balance ASC, id ASC) AS balance_bucket, PERCENT_RANK() OVER (PARTITION BY account_type ORDER BY balance DESC) AS balance_percent_rank FROM accounts) SELECT id, customer_id, account_type, balance, opened_date, status, first_known_balance FROM enriched;
